<x-layouts.workspace title="Public navigation" :ministry-name="$settings->name" :primary-color="$settings->primary_color" :accent-color="$settings->accent_color" :user-name="$user->name" user-role="Staff workspace">
<x-slot:navigation></x-slot:navigation>
<header class="workspace-page-heading staff-page-command"><div><p>PUBLIC SITE</p><h1>Navigation</h1><span>Build the menu visitors see across the public website. Add icons, dropdown links, and module-aware destinations.</span></div><a class="button button-secondary" href="{{ route('staff.pages') }}">Pages</a></header>
@if(session('status'))<div class="workspace-notice workspace-notice-success">{{ session('status') }}</div>@endif @if($errors->any())<div class="workspace-notice workspace-notice-error">{{ $errors->first() }}</div>@endif
<section class="navigation-destinations"><header><div><p>AVAILABLE DESTINATIONS</p><h2>Add pages without typing a link</h2><span>Choose a public page, a published custom page, or a member-area page. You can edit its icon, order, and visibility afterwards.</span></div><span>{{ count($destinations) }} destinations</span></header><div class="navigation-destination-grid">@foreach(collect($destinations)->groupBy('group') as $group => $links)<section><h3>{{ $group }}</h3><div>@foreach($links as $link)<form method="POST" action="{{ route('staff.navigation.store') }}">@csrf<input type="hidden" name="label" value="{{ $link['label'] }}"><input type="hidden" name="url" value="{{ $link['url'] }}"><input type="hidden" name="icon" value="{{ $link['icon'] }}"><input type="hidden" name="visible_desktop" value="1"><input type="hidden" name="visible_mobile" value="1"><button type="submit"><x-ui.icon :name="$link['icon']" :size="16"/><span><strong>{{ $link['label'] }}</strong><small>{{ $link['url'] }}</small></span><b>+</b></button></form>@endforeach</div></section>@endforeach</div></section><section class="navigation-manager"><aside class="navigation-add"><p>ADD A LINK</p><h2>Menu item</h2><form method="POST" action="{{ route('staff.navigation.store') }}">@csrf @include('staff.navigation-fields',['item'=>null])<button class="button" type="submit"><x-ui.icon name="add" :size="15"/> Add menu item</button></form></aside><main class="navigation-list"><header><div><p>PUBLIC MENU</p><h2>Order and manage links</h2><span>Top-level links appear first. Assign a parent to create a dropdown item.</span></div><span>{{ $items->count() }} links</span></header><div data-navigation-order>@forelse($items as $item)<article class="navigation-item" draggable="true" data-navigation-id="{{ $item->id }}"><div class="navigation-item-summary"><span class="navigation-drag">⋮⋮</span>@if($item->icon)<x-ui.icon :name="$item->icon" :size="17"/>@endif<div><strong>{{ $item->label }}</strong><small>{{ $item->url }} @if($item->parent_id) · Dropdown item @endif @if($item->required_feature) · {{ str($item->required_feature)->headline() }} module @endif</small></div><span class="table-status">{{ $item->visible_desktop ? 'Desktop' : 'Hidden desktop' }} · {{ $item->visible_mobile ? 'Mobile' : 'Hidden mobile' }}</span><details data-dismiss-on-outside><summary>Edit</summary><form method="POST" action="{{ route('staff.navigation.update',$item->id) }}">@csrf @method('PUT') @include('staff.navigation-fields',['item'=>$item])<button class="button" type="submit">Save link</button></form><form method="POST" action="{{ route('staff.navigation.destroy',$item->id) }}">@csrf @method('DELETE')<button class="button button-secondary" type="submit">Remove link</button></form></details></div></article>@empty<div class="empty-cell">No custom navigation yet. Add a link for pages, events, locations, or an external destination.</div>@endforelse</div><form method="POST" action="{{ route('staff.navigation.reorder') }}" data-navigation-order-form>@csrf @method('PUT')<input type="hidden" name="items" data-navigation-order-input><button class="button button-secondary" type="submit">Save menu order</button></form></main></section>
<script>(()=>{const form=document.querySelector('[data-navigation-order]');if(!form)return;const input=document.querySelector('[data-navigation-order-input]');let dragging;const save=()=>input.value=JSON.stringify([...form.querySelectorAll('[data-navigation-id]')].map(node=>node.dataset.navigationId));form.querySelectorAll('[data-navigation-id]').forEach(node=>{node.addEventListener('dragstart',()=>{dragging=node;node.classList.add('is-dragging')});node.addEventListener('dragover',event=>event.preventDefault());node.addEventListener('drop',event=>{event.preventDefault();if(dragging&&dragging!==node){node.parentNode.insertBefore(dragging,node);save()}});node.addEventListener('dragend',()=>node.classList.remove('is-dragging'))});save()})();</script>
</x-layouts.workspace>